import{_ as i,C as r,o as a,c as n,j as t,a as s,E as d,a2 as l}from"./chunks/framework.B5uwLxFG.js";const w=JSON.parse('{"title":"Free Online Audio Trimmer with Waveform","description":"Trim MP3, WAV, M4A, Ogg, Opus, FLAC, and AAC audio with an interactive waveform. Export Ogg, MP3, M4A, or WAV locally.","frontmatter":{"title":"Free Online Audio Trimmer with Waveform","description":"Trim MP3, WAV, M4A, Ogg, Opus, FLAC, and AAC audio with an interactive waveform. Export Ogg, MP3, M4A, or WAV locally.","pageClass":"crop-tool-layout","permalink":"/trimaudio/","canonicalUrl":"https://curvednebula.com/trimaudio/","meta":[{"name":"keywords","content":"trim audio online, audio cutter online, MP3 trimmer, WAV trimmer, audio waveform editor, cut audio in browser, private audio trimmer"},{"property":"og:title","content":"Free Online Audio Trimmer with Waveform"},{"property":"og:description","content":"Select a range on an interactive waveform and export trimmed Ogg, MP3, M4A, or WAV audio locally in your browser."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/trimaudio/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free Online Audio Trimmer with Waveform"},{"name":"twitter:description","content":"Trim audio against an interactive waveform without uploading your file."}],"aside":false},"headers":[],"relativePath":"trimaudio/index.md","filePath":"trimaudio/README.md"}'),u={name:"trimaudio/index.md"};function c(m,e,p,h,g,A){const o=r("AudioTrim");return a(),n("div",null,[e[0]||(e[0]=t("h1",{id:"trim-audio-online",tabindex:"-1"},[s("Trim Audio Online "),t("a",{class:"header-anchor",href:"#trim-audio-online","aria-label":'Permalink to "Trim Audio Online"'},"​")],-1)),d(o),e[1]||(e[1]=l('<h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Cut unwanted time from the beginning or end of an audio file using an interactive waveform. Click or drag the waveform to move the playhead, drag either edge handle to select the part to keep, preview the selection, and export it as Ogg Opus, MP3, M4A AAC, or WAV audio.</p><p>The waveform is generated incrementally from short regions distributed across the track. Each decoded sample is reduced into a waveform peak and released immediately, so the entire audio file is not retained in browser memory. Your audio stays on your device and is never uploaded.</p><h2 id="how-to-trim-audio" tabindex="-1">How to trim audio <a class="header-anchor" href="#how-to-trim-audio" aria-label="Permalink to &quot;How to trim audio&quot;">​</a></h2><ol><li>Select an audio file or drag it into the trimmer.</li><li>Click or drag the waveform to navigate through the audio.</li><li>Drag the waveform edge handles to select the range to keep, or enter exact start and end timestamps.</li><li>Preview the selected range with the play button.</li><li>Choose an output format and bitrate, then select <strong>Save Audio</strong>.</li></ol><h2 id="browser-compatibility" tabindex="-1">Browser compatibility <a class="header-anchor" href="#browser-compatibility" aria-label="Permalink to &quot;Browser compatibility&quot;">​</a></h2><p>Recent Chromium-based browsers such as Chrome and Edge provide the best compatibility. Audio export requires WebCodecs and must run in a secure browser context such as HTTPS.</p><p><strong>Input files supported:</strong> MP3, WAV/WAVE, M4A, Ogg/OGA, Opus, FLAC, and AAC.</p><ul><li><strong>MP3 and WAV:</strong> Generally provide the broadest input compatibility.</li><li><strong>M4A and AAC:</strong> Browser- and operating-system-specific. M4A is a container, so the audio codec inside it must also be supported; AAC is the most common.</li><li><strong>Ogg, Opus, and FLAC:</strong> Support varies between browsers and operating systems.</li><li>An accepted filename extension does not guarantee that a file can be edited. The browser must be able to play the file for preview and decode its exact codec through WebCodecs for waveform generation and export.</li></ul><p><strong>Output files supported:</strong> Ogg Opus, MP3, M4A AAC, and uncompressed 16-bit WAV.</p><ul><li><strong>WAV PCM:</strong> The most dependable output choice. It does not require a compressed-audio encoder, but the browser must still be able to decode the input audio.</li><li><strong>Ogg Opus:</strong> Requires an Opus <code>AudioEncoder</code> and is available only when the current browser reports support.</li><li><strong>M4A AAC:</strong> Browser-specific. AAC encoding may be unavailable in Firefox or on desktop Linux.</li><li><strong>MP3:</strong> Highly browser-specific and usually unavailable because current major browsers do not normally expose an MP3 <code>AudioEncoder</code>.</li><li>Unsupported compressed formats are disabled automatically in the output selector. Safari added WebCodecs audio encoding and decoding in Safari 26, so earlier Safari versions cannot export audio with this tool.</li></ul>',11))])}const f=i(u,[["render",c]]);export{w as __pageData,f as default};
